"""Source-backed layout studies; writes only this preview directory."""
import html
import json
import re
from pathlib import Path
from html.parser import HTMLParser

HERE=Path(__file__).resolve().parent
ROOT=HERE.parents[2]
class Extract(HTMLParser):
    def __init__(self): super().__init__(); self.entries=[];self.emblem='';self.gallery=[];self.figure=False
    def handle_starttag(self,tag,attrs):
        a=dict(attrs)
        if 'data-hand-explorer' in a:self.entries=json.loads(a['data-hand-explorer'])['entries']
        if tag=='figure' and 'hand-gallery-slide' in a.get('class',''):self.figure=True
        if tag=='img' and self.figure:self.gallery.append((a['src'],a.get('alt','')))
    def handle_endtag(self,tag):
        if tag=='figure':self.figure=False
source=(ROOT/'website/site/hands/generated/shadow-hand/index.html').read_text(encoding='utf-8')
extract=Extract();extract.feed(source)
emblem=re.search(r'<svg[^>]*class="dex-emblem".*?</svg>',source,re.S)
emblem=emblem[0] if emblem else ''
data=json.loads((ROOT/'website/site/visual-lab/specimens.json').read_text(encoding='utf-8'))
(HERE/'specimens.json').write_text(json.dumps(data,ensure_ascii=False),encoding='utf-8')
(HERE/'detail-data.json').write_text(json.dumps(extract.entries,ensure_ascii=False),encoding='utf-8')

THEMES={
 'paper':('01 · 暖纸白 / 炭黑 / 砖红','#f4f1ea','#fffdf8','#292b29','#696d67','#d8d8ce','#aa4d3e'),
 'slate':('02 · 石墨灰 / 雾白 / 灰绿','#15191f','#1d232b','#edf0f3','#a8b2bf','#343c47','#87b5ac'),
 'white':('03 · 冷白 / 深灰 / 钴蓝','#f5f6f8','#ffffff','#252d38','#647080','#dce1e8','#3c65ae'),
 'plum':('04 · 墨紫灰 / 珍珠白 / 灰紫','#191923','#222330','#f0eef5','#b5b4c5','#383947','#b7a4db'),
}
theme_css='\n'.join(f'body[data-theme={k}]{{--bg:{v[1]};--surface:{v[2]};--ink:{v[3]};--muted:{v[4]};--line:{v[5]};--accent:{v[6]}}}' for k,v in THEMES.items())
